/**
 * Real-Data Adapter for BurnInWatch 3D Digital Twin
 *
 * Loads real pipeline output from `public/digitalTwin/replay.json` (generated by
 * `scripts/exportDigitalTwinReplay.py` from `processed/sample_burnin_device4_main.csv`
 * using the real `response_focused` Isolation Forest & Autoencoder models).
 *
 * Citation:
 * Trained models and thresholds loaded from `backend/models/` and `burninwatch_expanded_artifacts_v2.json`.
 */

import { SensorValues, ModelTelemetry } from '../demoData';

export interface ReplayWindowFeature {
  feature: string;
  squared_error: number;
}

export interface ReplayWindow {
  window_index: number;
  start_row: number;
  end_row: number;
  start_time: number;
  end_time: number;
  sensors: SensorValues;
  if_score: number;
  ae_error: number;
  if_flag: boolean;
  ae_flag: boolean;
  consensus: 'NORMAL' | 'REVIEW' | 'ANOMALY';
  top_features: ReplayWindowFeature[];
  top_signals: string[];
}

export interface ReplayEpisode {
  id: number;
  first_window: number;
  last_window: number;
  start_row: number;
  end_row: number;
  start_time: number;
  end_time: number;
  duration_s: number;
  windows_count: number;
  span_windows: number;
  max_if_score: number;
  max_ae_score: number;
  max_ae_to_threshold: number;
  agreement_pct: number;
  peak_window: number;
  top_signals: string[];
}

export interface SignalRangeStat {
  min: number;
  mean: number;
  std: number;
  p01: number;
  p99: number;
}

export interface ReplayDataset {
  metadata: {
    source: string;
    file: string;
    device_id: string;
    model_name: string;
    total_rows: number;
    window_size: number;
    stride: number;
    total_windows: number;
    duration_s: number;
    citation: string;
  };
  thresholds: {
    isolation_forest: number;
    autoencoder: number;
  };
  summary: {
    status: 'NORMAL' | 'REVIEW' | 'ANOMALY';
    total_windows: number;
    normal_windows: number;
    review_windows: number;
    anomalous_windows: number;
    anomaly_fraction: number;
    max_if_score: number;
    max_ae_score: number;
  };
  episodes: ReplayEpisode[];
  signal_stats: Record<string, SignalRangeStat>;
  windows: ReplayWindow[];
}

/**
 * Validates the parsed JSON against the strict ReplayDataset schema.
 */
export function validateReplayData(raw: unknown): ReplayDataset {
  if (!raw || typeof raw !== 'object') {
    throw new Error('Replay data is empty or not a valid JSON object.');
  }

  const obj = raw as Record<string, unknown>;

  if (!obj.metadata || typeof obj.metadata !== 'object') {
    throw new Error('Missing metadata section in replay JSON.');
  }

  if (!obj.thresholds || typeof obj.thresholds !== 'object') {
    throw new Error('Missing thresholds section in replay JSON.');
  }

  const thresh = obj.thresholds as Record<string, unknown>;
  if (typeof thresh.isolation_forest !== 'number' || typeof thresh.autoencoder !== 'number') {
    throw new Error('Invalid thresholds: isolation_forest and autoencoder must be numbers.');
  }

  if (!Array.isArray(obj.windows) || obj.windows.length === 0) {
    throw new Error('Replay data has no windows array or it is empty.');
  }

  const firstWin = obj.windows[0];
  if (
    typeof firstWin.window_index !== 'number' ||
    !firstWin.sensors ||
    typeof firstWin.if_score !== 'number' ||
    typeof firstWin.ae_error !== 'number' ||
    typeof firstWin.consensus !== 'string'
  ) {
    throw new Error('Replay windows missing required fields (window_index, sensors, if_score, ae_error, consensus).');
  }

  return raw as ReplayDataset;
}

/**
 * Fetches the pre-exported real pipeline output from public/digitalTwin/replay.json.
 */
export async function loadRealReplayDataset(): Promise<ReplayDataset> {
  const response = await fetch('/digitalTwin/replay.json');
  if (!response.ok) {
    throw new Error(`Failed to load real replay data (HTTP ${response.status} ${response.statusText})`);
  }
  const json = await response.json();
  return validateReplayData(json);
}

/**
 * Maps a ReplayWindow to the internal ModelTelemetry structure used by the HUD.
 */
export function toModelTelemetry(
  window: ReplayWindow,
  thresholds: { isolation_forest: number; autoencoder: number }
): ModelTelemetry {
  return {
    ifScore: window.if_score,
    ifThreshold: thresholds.isolation_forest,
    ifFlagged: window.if_flag,
    aeLoss: window.ae_error,
    aeThreshold: thresholds.autoencoder,
    aeFlagged: window.ae_flag,
    consensus: window.consensus,
    windowIndex: window.window_index,
    leadingFeatures: window.top_signals,
  };
}

/**
 * Returns a list of window indices that were flagged by either model (REVIEW or ANOMALY).
 */
export function getFlaggedWindowIndices(dataset: ReplayDataset): number[] {
  return dataset.windows
    .filter((w) => w.consensus !== 'NORMAL')
    .map((w) => w.window_index);
}
